extern "C" __global__ void __launch_bounds__(256) k1(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int n,float e){body<1>(q,k,wq,wk,qo,ko,n,e);}
extern "C" __global__ void __launch_bounds__(256) k2(const float* q,const float* k,const float* wq,const float* wk,float* qo,float* ko,int n,float e){body<2>(q,k,wq,wk,qo,ko,n,e);}
